  "code": "export default async function ({ page, context }) {
  const cookies = {{ JSON.stringify($json.session.cookies) }};
  const targetUrl = '{{ $json.session.url }}';

  await page.setViewport({ width: 1280, height: 800 });

  // Restaurar cookies
  if (cookies && cookies.length > 0) {
    await page.setCookie(...cookies);
  }

  await page.goto(targetUrl, { waitUntil: 'networkidle2', timeout: 30000 });
  await new Promise(r => setTimeout(r, 2000));

  // Screenshot
  const screenshot = await page.screenshot({ encoding: 'base64', fullPage: false });

  // Listar elementos clicaveis
  const clickables = await page.$$eval('a, button, input, select, [onclick], [role="button"]', els => els.map((el, index) => {
    const rect = el.getBoundingClientRect();
    return {
      i: index,
      tag: el.tagName,
      text: (el.textContent || '').trim().substring(0, 60),
      type: el.type || null,
      placeholder: el.placeholder || null,
      x: Math.round(rect.x + rect.width/2),
      y: Math.round(rect.y + rect.height/2),
      vis: rect.width > 0 && rect.height > 0 && rect.y < 800
    };
  }).filter(el => el.vis));

  return {
    url: page.url(),
    screenshot: screenshot,
    elementos: clickables.slice(0, 40),
    cookies: await page.cookies()
  };
}"
}

