const captura = $('2. Captura Tela').first().json;
const iaResponse = $input.first().json;

let iaDecisao;
try {
  let content = iaResponse.choices[0].message.content;
  if (content.includes('```')) {
    content = content.replace(/```json?\n?/g, '').replace(/```/g, '');
  }
  iaDecisao = JSON.parse(content.trim());
} catch (e) {
  iaDecisao = { acao: 'erro', motivo: 'Falha parse: ' + iaResponse.choices[0].message.content };
}

return [{
  json: {
    ...iaDecisao,
    url: captura.url,
    cookies: captura.cookies,
    elementos: captura.elementos
  }
}];

